from typing import Union, Generic, TypeVar

T = TypeVar('T')

class Result(Generic[T]):
    pass

class Ok(Result[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self) -> str:
        return f"Ok({self.value})"

class Err(Result[T]):
    def __init__(self, message: str):
        self.message = message

    def __repr__(self) -> str:
        return f"Err({self.message})"

def parse_int(s: str) -> Result[int]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def format_result(result: Result[int]) -> str:
    if isinstance(result, Ok):
        return f"Result: {result.value}"
    elif isinstance(result, Err):
        return f"Error: {result.message}"

def chain_operations(s: str, divisor: int) -> str:
    parsed = parse_int(s)
    if isinstance(parsed, Ok):
        result = divide_safe(parsed.value, divisor)
        return format_result(result)
    else:
        return format_result(parsed)

print(chain_operations("10", 2))
print(chain_operations("10", 0))
print(chain_operations("abc", 2))

