from typing import Union, TypeVar, Callable

T = TypeVar('T')
U = TypeVar('U')

class Some:
    def __init__(self, value: T):
        self.value = value

    def __repr__(self) -> str:
        return f"Some({self.value})"

    def __eq__(self, other) -> bool:
        return isinstance(other, Some) and self.value == other.value

class Nothing:
    def __repr__(self) -> str:
        return "Nothing"

    def __eq__(self, other) -> bool:
        return isinstance(other, Nothing)

Option = Union[Some, Nothing]

def findFirst(predicate: Callable[[T], bool], lst: list[T]) -> Option:
    """Find first element matching predicate, return Some(element) or Nothing"""
    for element in lst:
        if predicate(element):
            return Some(element)
    return Nothing()

def mapOption(fn: Callable[[T], U], option: Option) -> Option:
    """Apply function to value if Some, otherwise return Nothing"""
    if isinstance(option, Some):
        return Some(fn(option.value))
    else:
        return Nothing()

def print_option(option: Option, label: str) -> None:
    """Print option result in readable format"""
    if isinstance(option, Some):
        print(f"Found: {option.value}")
    else:
        print("Not found")

