type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(t: Tree) -> int {
  match t {
    Leaf(v) => v,
    Node(Leaf(lv), v, Leaf(rv)) => {
      let m1 = if lv >= v then lv else v;
      if m1 >= rv then m1 else rv
    },
    Node(l, v, r) if v >= find_max(l) && v >= find_max(r) => v,
    Node(l, v, r) => {
      let lmax = find_max(l);
      let rmax = find_max(r);
      if lmax >= rmax then lmax else rmax
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let sum = tree_sum(tree);
  let maxv = find_max(tree);
  println("Sum: " ++ show(sum));
  println("Max: " ++ show(maxv))
}

